import{spaceFigure}from './spa1-figures.js?v=20261023-physicscomplete01';
const entries=[['system','From nebula to main sequence',['Gravity draws gas and dust inward.','The protostar contracts and heats.','Core temperature/pressure rise.','Fusion can begin and support a stable main-sequence star.']],['stars','A Sun-like stellar pathway',['Gas and dust form a nebula.','Gravity forms a hot protostar.','Main-sequence fusion maintains the star.','The star expands into a red giant.','Outer layers are shed.','A white-dwarf remnant cools.']],['orbits','Inward force, tangent velocity',['Gravity points toward the central body.','Velocity is tangent to the circular path.','Direction changes while speed can stay constant.','The same inward interaction continues around the orbit.']],['redshift','Longer wavelengths and expanding space',['Match reference and observed spectral features.','Observed features shift toward longer wavelength.','The separation of galaxy markers increases in the analogy.','The distance–recession pattern supports expansion.']]];
export const spa1Films=Object.fromEntries(entries.map(([k,title,steps])=>['spa1-'+k,{title,steps,duration:18,render:p=>spaceFigure({kind:k,movie:true,progress:p}),note:'Original schematic. Body sizes, orbit separations, star-stage durations and cosmological times are independently scaled. Replay resets the example; stellar evolution is not reversed. The Sun-like film is a separate worked pathway from the selected high-mass comparison. Circular-orbit vectors show directions, not a numerical gravity simulation. Redshift/grid expansion is an analogy, not a measured cosmological relation or a claim that Earth is a special centre. Specialist review and independent extended explanations remain separate.'}]));
